const check = (name, cond, detail = '') => { results.push({ name, ok: !!cond, detail }); console.log(`${cond ? '  ✓' : '  ✗'} ${name}${detail ? ' — ' + detail : ''}`); };
const now = Date.now();
const seed = ({ now, limit }) => { if (localStorage.getItem('scalpdesk.savedat.v1')) return;
