async function open(browser, view, { init = [], limit = null, quietFutures = false } = {}) {
  const ctx = await browser.newContext(view); for (const [fn, arg] of [[seed, { now, limit }], ...init]) await ctx.addInitScript(fn, arg);
  if (quietFutures) await ctx.addInitScript(() => {
    const trace = (event, extra = {}) => console.info('M7_LEAVE_DIAG ' + JSON.stringify({ event, at: Date.now(), hidden: document.hidden, positions: window.__g05?.state.positions.length, status: document.getElementById('tgb-info')?.textContent, ...extra }));
