      const method = String(url).match(/\/(sendDocument|editMessageMedia|pinChatMessage|getChat)(?:[?]|$)/)?.[1];
      if (method) trace('fetch', { method, keepalive: options?.keepalive === true, fileSize: options?.body instanceof FormData ? [...options.body.values()].filter(x => x instanceof Blob).map(x => x.size) : [] });
      return original.apply(this, arguments);
    };
  });
